    private static int[] parse(String line) {
        String[] inputsStr = line.split(" ");
        int[] result = new int[inputsStr.length];

        for (int i = 0; i < inputsStr.length; i++) {
            result[i] = Integer.parseInt(inputsStr[i]);
        }

        return result;
    }
