         fac[0] = 1L;   invfac[0] = 1L;
         for(int i=1; i <= N+4; i++)
         {
            fac[i] = (fac[i-1]*i)%MOD;
            invfac[i] = power(fac[i], MOD-2, MOD);
         }
         int tag = -1;
