         StringBuilder sb = new StringBuilder(N+"\n");
         for(int k=2; k <= N+1; k++)
         {
            long total = (fac[N+1]*invfac[N+1-k])%MOD;
            total = (total*invfac[k])%MOD;
            if(ends-k+1 >= 0)
            {
               long extra = (fac[ends]*invfac[k-1])%MOD;
               extra = (extra*invfac[ends-k+1])%MOD;
               total -= extra;
            }
            if(total < 0)  total += MOD;
            sb.append(total+"\n");
         }
         System.out.print(sb);
