		col = new int[W + 1];

		for(int i = 0;i < N;i++){
			int x = nextInt();
			int y = nextInt();
			int w = nextInt();

			row[Math.max(0,y - w)]++;
			row[Math.min(H, y + w)]--;

			col[Math.max(0, x - w)]++;
			col[Math.min(W, x + w)]--;
		}

		for(int i = 0;i < H;i++){
			row[i + 1] += row[i];
		}

		for(int i = 0;i < W;i++){
			col[i + 1] += col[i];
		}

