	public static boolean nextPermutation(ArrayList<Integer> nums) {
		if(nums.size() < 2) return false;
		int i = nums.size() - 2;
		for(;i >= 0 && nums.get(i) > nums.get(i+1);i--);
		if(i<0) return false;
		int j = i + 1;
		int k = nums.size() - 1;
		for(;nums.get(i) > nums.get(k); k--);
		int tmp = nums.get(i);
		nums.set(i, nums.get(k));
		nums.set(k, tmp);
