		List<Integer> tmpList = (List<Integer>) nums.clone();
		Collections.reverse(tmpList);
		while(tmpList.size()>nums.size() - j) tmpList.remove(tmpList.size()-1);
		while(nums.size()>j) nums.remove(nums.size()-1);
		nums.addAll(tmpList);
		return true;
	}
