					vz[i]=sc.nextDouble();
					r[i]=sc.nextDouble();
					vr[i]=sc.nextDouble();
				}
				PriorityQueue<State> pq=new PriorityQueue<>();

				for(int i=0; i<n; i++) {
					if(vr[i]!=0) {
						time[i]=r[i]/vr[i];
					}
