	void solve(){
		LinkedList<State> que=new LinkedList<State>();
		boolean[] visited=new boolean[1<<(n*n)];

		int[] removed=new int[n];
		for(int i=0; i<n; i++){
			fill(removed, (1<<n)-1);
		}

		State s0=new State(0, removed);
		que.offer(s0);
		visited[s0.hashCode()]=true;

		for(; !que.isEmpty();){
			State s=que.poll();
			for(int k=0; k<nRs; k++){
				for(int y=-n+1; y<n; y++){
					for(int x=-n+1; x<n; x++){
						if(canStamp(x, y, rs[k].w, rs[k].h, s.removed)){
							State t=new State(s.step+1, s.removed);
							t.clear(x, y, rs[k].w, rs[k].h);
							if(!visited[t.hashCode()]){
								que.offer(t);
								visited[t.hashCode()]=true;
								if(t.isCleared()){
									println(t.step+"");
									return;
								}
							}
						}
					}
				}
			}
		}
	}

	boolean canStamp(int x, int y, int w, int h, int[] removed){
		boolean same=true;
		int k=0;
		for(int j=y; j<y+h; j++){
			for(int i=x; i<x+w; i++){
				if(i>=0&&i<n&&j>=0&&j<n){
					if(((removed[j]>>i)&1)!=0){
						if(k==0){
							k=map[j][i];
						}else{
							same&=k==map[j][i];
						}
					}
					if(!same){
						return false;
					}
				}
			}
		}
		return same&&k!=0;
	}

