		int[] removed=new int[n];

		State(int step, int[] rem){
			this.step=step;
			for(int i=0; i<n; i++){
				removed[i]=rem[i];
			}
		}

		void clear(int x, int y, int w, int h){
			for(int j=y; j<y+h; j++){
				for(int i=x; i<x+w; i++){
					if(i>=0&&i<n&&j>=0&&j<n){
						removed[j]&=~(1<<i);
					}
				}
			}
		}

		boolean isCleared(){
			boolean ret=true;
			for(int i=0; i<n; i++){
				ret&=removed[i]==0;
			}
			return ret;
		}

		@Override
