			l[i] = sc.nextInt();
			sum += l[i];
		}

		int ans = Integer.MAX_VALUE;
		for(int left = 0; left < n; left++) {
			int low = 0;
			for(int right = left; right < n; right++) {
				low += l[right];
				int[] dp = new int[n + 1];
				dp[0] = low;

				for(int position = 0; position < n; position++) {
					int length = 0;
					dp[position + 1] = Integer.MAX_VALUE;

					for(int le = position; le >= 0; le--) {
						length += l[le];

