            List<Long> list = new ArrayList<>();
            int before = 0;
            for (int i = N - 1; i >= 0; i--) {
                if (before != A[i]) {
                    before = A[i];
                } else {
                    list.add((long) A[i]);
                    before = 0;
                }
                if (list.size() == 2) break;
            }

            long ans = 0;
            if (list.size() == 2)
                ans = list.get(0) * list.get(1);
            out.println(ans);
