		if(sS == CHECK && tS == CHECK) return cost;
		int ret = INF;
		for(int i = 0; i < s.length; i++) {
			if((sS & 1 << i) != 0 || dp[now][s[i]] == INF) continue;
			ret = Math.min(ret, dfs(s[i],sS | 1 << i,tS,cost + dp[now][s[i]]));
