		for(int i = 0; i < t.length; i++) {
			if((tS & 1 << i) != 0 || (sS & 1 << i) == 0 || dp[now][t[i]] == INF) continue;
			ret = Math.min(ret, dfs(t[i],sS,tS | 1 << i,cost + dp[now][t[i]]));
