			this.y = p.y;
			this.x = p.x;
			board = new int[N][N];
			for(int i=0; i<N; i++) { for(int j=0; j<N; j++) { board[i][j] = p.board[i][j]; } }
		}

		public String getString() {
			String str = "";
			for(int i=0; i<N; i++) { for(int j=0; j<N; j++) { str += Integer.toString(board[i][j]); } }
			return str;
		}

		public void swap(int ny, int nx) {
			int tmp = board[y][x];
			board[y][x] = board[ny][nx];
			board[ny][nx] = tmp;
			y = ny;
			x = nx;
		}

