            d = dist[i, j]
            for k in xrange(i+1, n):
                lp, rp = P[k]
                # update left and right
                if left is None or cross((x, y), left, lp) >= 0:
                    left = lp
                if right is None or cross((x, y), rp, right) >= 0:
                    right = rp
                # check if left <= right
                if cross((x, y), left, right) < 0:
