		node NEW=new node();
		NEW.v=n;
		NEW.next=END;
		NEW.prev=END.prev;
		NEW.prev.next=NEW;
		END.prev=NEW;
		size++;
	}

	private void pdelete(node N) {
		NOW.next.prev=NOW.prev;
		NOW.prev.next=NOW.next;
	}

	void unique() {
		NOW=END.next;
		int n=NOW.v,dsize=0;
		NOW=NOW.next;
		for(int i=1;i<size;i++) {
			if(NOW.v==n) {
				pdelete(NOW);
				dsize++;
			}
			else n=NOW.v;
			NOW=NOW.next;
		}
		size-=dsize;
	}

