		PriorityQueue<Edge> que = new PriorityQueue<Main.Edge>();
		for (int i = 0; i < m; ++i) {
			Edge e = new Edge(u[i], v[i], w[i], l[i]);
			if (l[i] == 'A')
				e.cost += add;
			que.add(e);
		}

		DJSet ds = new DJSet(n);
		int weight = 0;
		int cnt = 0;
		while (!que.isEmpty()) {
			Edge e = que.poll();
			if (ds.equiv(e.src, e.dst))
				continue;
			weight += e.cost;
			ds.setUnion(e.src, e.dst);
			if (e.c == 'A') {
				++cnt;
			}
		}
		return new int[] { weight - k * add, cnt };
	}

	static class DJSet {
		int n;
		int[] upper;

		public DJSet(int n) {
			this.n = n;
			upper = new int[n];
			Arrays.fill(upper, -1);
		}

		boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		int root(int x) {
			return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
		}

		void setUnion(int x, int y) {
			x = root(x);
			y = root(y);
			if (x == y)
				return;
			if (upper[x] > upper[y]) {
				int tmp = x;
				x = y;
				y = tmp;
			}
			upper[x] += upper[y];
			upper[y] = x;
		}
	}

